from typing import List

def count_completed_trips(logs: List[str]) -> int:
    state = {}  # plate -> "init" / "entry" / "road"
    count = 0
    for log in logs:
        plate, event = log.split()
        s = state.get(plate, "init")
        if event == "entry":
            state[plate] = "entry"          # 新的 entry 总是开启一段新行程
        elif event == "road":
            state[plate] = "road" if s == "entry" else "init"
        elif event == "exit":
            if s == "road":
                count += 1
            state[plate] = "init"
    return count

if __name__ == "__main__":
    assert count_completed_trips(["A entry", "A road", "A exit"]) == 1
    assert count_completed_trips(["A entry", "B entry", "A road", "A exit", "B exit"]) == 1
    print("ok")
